'use client';

import { Loader2 } from 'lucide-react';
import { useTranslations } from 'next-intl';
import { useRouter } from 'next/navigation';
import { useEffect, useState } from 'react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';

const INTERVAL_MS = 2000;
const MAX_MS = 60_000;

/** Shown while a paid order's tickets/invoice are still being generated by the worker. */
export function OrderAutoRefresh() {
  const t = useTranslations('checkout.order.preparing');
  const router = useRouter();
  const [timedOut, setTimedOut] = useState(false);

  useEffect(() => {
    const started = Date.now();
    const timer = setInterval(() => {
      if (Date.now() - started >= MAX_MS) {
        clearInterval(timer);
        setTimedOut(true);
        return;
      }
      router.refresh();
    }, INTERVAL_MS);
    return () => clearInterval(timer);
  }, [router]);

  return (
    <Alert role="status">
      {!timedOut && <Loader2 className="size-4 animate-spin" />}
      <AlertTitle>{timedOut ? t('timeoutTitle') : t('title')}</AlertTitle>
      <AlertDescription>{timedOut ? t('timeoutText') : t('text')}</AlertDescription>
    </Alert>
  );
}
